I have a C program that processes user input strings. It works for short inputs but crashes with a segfault for longer ones. I've been staring at it for hours.

```c
#include <stdio.h>
#include <string.h>

void format_greeting(const char *name) {
    char buffer[32];
    sprintf(buffer, "Hello, %s! Welcome to our platform.", name);
    printf("%s\n", buffer);
}

void process_input(const char *input) {
    char command[16];
    char argument[64];

    // Parse "command:argument" format
    char *colon = strchr(input, ':');
    if (colon) {
        int cmd_len = colon - input;
        strncpy(command, input, cmd_len);
        command[cmd_len] = '\0';
        strcpy(argument, colon + 1);
    }

    if (strcmp(command, "greet") == 0) {
        format_greeting(argument);
    }
}

int main() {
    char input[256];
    fgets(input, sizeof(input), stdin);
    input[strcspn(input, "\n")] = '\0';
