  const [results, setResults] = useState<Product[]>([]);
  const [loading, setLoading] = useState(false);
  const [debouncedQuery, setDebouncedQuery] = useState('');

  useEffect(() => {
    const id = setTimeout(() => setDebouncedQuery(query), 300);
    return () => clearTimeout(id);
  }, [query]);

  useEffect(() => {
    if (!debouncedQuery) { setResults([]); return; }
    const controller = new AbortController();
    setLoading(true);
    fetch(`/api/products?q=${encodeURIComponent(debouncedQuery)}`, { signal: controller.signal })
      .then(r => r.json())
      .then((data: Product[]) => {
        setResults(data);
        setLoading(false);
      })
      .catch(err => { if (err.name !== 'AbortError') setLoading(false); });
    return () => controller.abort();
  }, [debouncedQuery]);

  const grouped = useMemo(() => {
    return results.reduce<Record<string, Product[]>>((acc, p) => {
      (acc[p.category] ??= []).push(p);
      return acc;
    }, {});
  }, [results]);

  return /* ... */;
}
```

How would you decompose this? Concerned about testability mostly — right now I can't test any piece in isolation.

There are four distinct concerns tangled together. Pull them apart along their natural seams:

1. **`useDebounced<T>`** — delay-propagate a value. Pure time-based transformation.
2. **`useFetch<T>`** — URL in, `{ data, loading, error }` out, with cancellation.
3. **`groupBy`** — pure function, no hook needed.
4. **`ProductSearch`** — composition layer. UI only.

Each is independently testable because each has a narrow interface.

```tsx
// hooks/useDebounced.ts
export function useDebounced<T>(value: T, delayMs: number): T {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delayMs);
    return () => clearTimeout(id);
  }, [value, delayMs]);
  return debounced;
}
```

```tsx
// hooks/useFetch.ts
type FetchState<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: T }
  | { status: 'error'; error: Error };

export function useFetch<T>(url: string | null): FetchState<T> {
  const [state, setState] = useState<FetchState<T>>({ status: 'idle' });

  useEffect(() => {
    if (!url) { setState({ status: 'idle' }); return; }
    const controller = new AbortController();
    setState({ status: 'loading' });

    fetch(url, { signal: controller.signal })
      .then(r => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json() as Promise<T>;
      })
      .then(data => setState({ status: 'success', data }))
      .catch(error => {
        if (error.name === 'AbortError') return;
        setState({ status: 'error', error });
      });

    return () => controller.abort();
  }, [url]);

  return state;
}
```

Note the discriminated union — consumers can't accidentally render stale data while loading (the "flash of old results" bug) because `data` only exists when `status === 'success'`.

```tsx
// utils/groupBy.ts — pure, no React
export function groupBy<T, K extends keyof T>(list: T[], key: K): Record<string, T[]> {
  const result: Record<string, T[]> = {};
  for (const item of list) {
    const k = String(item[key]);
    (result[k] ??= []).push(item);
  }
  return result;
}
```

```tsx
// ProductSearch.tsx — composition only
function ProductSearch() {
  const [query, setQuery] = useState('');
  const debouncedQuery = useDebounced(query, 300);
  const url = debouncedQuery
    ? `/api/products?q=${encodeURIComponent(debouncedQuery)}`
    : null;
  const fetchState = useFetch<Product[]>(url);

  const grouped = useMemo(
    () => fetchState.status === 'success' ? groupBy(fetchState.data, 'category') : {},
    [fetchState]
  );

  return (
    <>
      <input value={query} onChange={e => setQuery(e.target.value)} />
      {fetchState.status === 'loading' && <Spinner />}
      {fetchState.status === 'error' && <ErrorBanner error={fetchState.error} />}
      {fetchState.status === 'success' && <Results grouped={grouped} />}
    </>
  );
}
```

The component is now six lines of logic and you can read what it does top-to-bottom.

**Testing each in isolation (Vitest + @testing-library/react + MSW).**

