```rust
use std::path::Path;
use wasmtime::component::{Component, Linker, ResourceTable};
use wasmtime::{Config, Engine, Store};
use wasmtime_wasi::{DirPerms, FilePerms, WasiCtx, WasiCtxBuilder, WasiView};
use wasmtime_wasi_http::bindings::http::types::ErrorCode;
use wasmtime_wasi_http::types::{HostFutureIncomingResponse, OutgoingRequestConfig};
use wasmtime_wasi_http::{WasiHttpCtx, WasiHttpView};

struct PluginState {
    ctx: WasiCtx,
    http: WasiHttpCtx,
    table: ResourceTable,
    allowed_host: String,
}

impl WasiView for PluginState {
    fn ctx(&mut self) -> &mut WasiCtx { &mut self.ctx }
    fn table(&mut self) -> &mut ResourceTable { &mut self.table }
}

impl WasiHttpView for PluginState {
    fn ctx(&mut self) -> &mut WasiHttpCtx { &mut self.http }
    fn table(&mut self) -> &mut ResourceTable { &mut self.table }

    fn send_request(
        &mut self,
        request: hyper::Request<wasmtime_wasi_http::body::HyperOutgoingBody>,
        config: OutgoingRequestConfig,
    ) -> wasmtime_wasi_http::HttpResult<HostFutureIncomingResponse> {
        let host = request.uri().host().unwrap_or("");
        if host != self.allowed_host {
            return Err(ErrorCode::HttpRequestDenied.into());
        }
        wasmtime_wasi_http::types::default_send_request(self, request, config)
    }
}

pub async fn run_plugin(
    plugin_path: &Path,
    data_dir: &Path,
    allowed_host: &str,
) -> anyhow::Result<()> {
    let mut config = Config::new();
    config.async_support(true).wasm_component_model(true);
    let engine = Engine::new(&config)?;

    let mut linker = Linker::<PluginState>::new(&engine);
    wasmtime_wasi::add_to_linker_async(&mut linker)?;
    wasmtime_wasi_http::add_only_http_to_linker_async(&mut linker)?;

    let ctx = WasiCtxBuilder::new()
        .preopened_dir(data_dir, "/data", DirPerms::READ, FilePerms::READ)?
        .inherit_stderr()                // for debugging only
        .build();

    let state = PluginState {
        ctx,
        http: WasiHttpCtx::new(),
        table: ResourceTable::new(),
        allowed_host: allowed_host.to_string(),
    };

    let mut store = Store::new(&engine, state);
    store.set_fuel(1_000_000_000)?;      // CPU bound (requires Config::consume_fuel)

    let component = Component::from_file(&engine, plugin_path)?;
    let instance = linker.instantiate_async(&mut store, &component).await?;

    let run = instance.get_typed_func::<(), (Result<(), String>,)>(&mut store, "run")?;
    let (result,) = run.call_async(&mut store, ()).await?;
    run.post_return_async(&mut store).await?;
    result.map_err(|e| anyhow::anyhow!("plugin failed: {e}"))
}
```

**What this enforces**

- **Filesystem**: only `data_dir` is visible, mapped as `/data` inside the guest, read-only. No stdin/stdout inherited (plugin can't exfiltrate via stdout unless you inherit it). Override with `DirPerms::MUTATE | FilePerms::WRITE` if they need to write.
- **HTTP**: every outbound request hits `send_request`. Check scheme, port, path if you want. Rejecting returns a proper WASI error the guest sees as a failed request, not a trap.
- **CPU**: `set_fuel` + `Config::consume_fuel(true)` lets you cap execution. Out-of-fuel traps the instance cleanly.
- **Memory**: add `config.max_wasm_stack(512 * 1024)` and a `ResourceLimiter` on the store to cap linear memory growth.

**Plugin side (Rust, wasm32-wasip2)**

Plugin authors use `cargo component` and write normal Rust:

```rust
// wit/plugin.wit
// package example:plugin;
// world plugin { export run: func() -> result<_, string>; }

wit_bindgen::generate!({ world: "plugin" });

struct MyPlugin;
impl Guest for MyPlugin {
    fn run() -> Result<(), String> {
        let data = std::fs::read_to_string("/data/input.json")
            .map_err(|e| e.to_string())?;
        // outbound http via wasi:http/outgoing-handler goes through
        // your filter — any host other than allowed_host returns an error
        Ok(())
    }
}
export!(MyPlugin);
```

**When preview 1 is still the right call**

If your plugin authors need Go (stdlib), or you're bolting onto an existing module-based plugin system, stay on preview 1 and accept that outbound HTTP requires either wasi-sockets (preview 1 extension, limited runtime support) or pushing HTTP out as a host function you define. You'd implement a custom `Linker::func_wrap("env", "http_get", ...)` that takes (ptr, len) for the URL and does the allowlist check host-side. Works, but you've just reinvented the wheel that `wasi:http` standardizes.

The crash at 10k is almost certainly from missing heartbeat cleanup (zombie connections accumulate) and O(n) broadcasts. Here is a connection manager built on the `ws` library that handles 50k connections on a single process:

```typescript
// connection-manager.ts — requires: npm install ws
// Run with: ts-node --esm connection-manager.ts

import { WebSocketServer, WebSocket, RawData } from "ws";
import { IncomingMessage } from "http";

interface ConnectionMeta {
  id: string;
  rooms: Set<string>;
  isAlive: boolean;
  connectedAt: number;
}

class ConnectionManager {
  private rooms = new Map<string, Set<WebSocket>>();
  private meta = new WeakMap<WebSocket, ConnectionMeta>();
  private connectionCount = 0;
  private heartbeatInterval: ReturnType<typeof setInterval> | null = null;

  constructor(
    private readonly wss: WebSocketServer,
    private readonly heartbeatMs: number = 30_000,
  ) {
    this.wss.on("connection", (ws, req) => this.handleConnection(ws, req));
    this.startHeartbeat();
  }

  private handleConnection(ws: WebSocket, req: IncomingMessage): void {
    const id = `conn_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    const meta: ConnectionMeta = {
      id,
      rooms: new Set(),
      isAlive: true,
      connectedAt: Date.now(),
    };
    this.meta.set(ws, meta);
    this.connectionCount++;

    ws.on("pong", () => {
      const m = this.meta.get(ws);
      if (m) m.isAlive = true;
    });

    ws.on("message", (data) => this.handleMessage(ws, data));
    ws.on("close", () => this.handleDisconnect(ws));
    ws.on("error", () => this.handleDisconnect(ws));
  }

  private handleMessage(ws: WebSocket, raw: RawData): void {
    let msg: { type: string; room?: string; payload?: unknown };
    try {
      msg = JSON.parse(raw.toString());
    } catch {
      return; // Ignore malformed messages.
    }

    switch (msg.type) {
      case "join":
        if (msg.room) this.joinRoom(ws, msg.room);
        break;
      case "leave":
        if (msg.room) this.leaveRoom(ws, msg.room);
        break;
      case "broadcast":
        if (msg.room && msg.payload) {
          this.broadcastToRoom(
            msg.room,
            JSON.stringify({ type: "message", room: msg.room, payload: msg.payload }),
            ws, // exclude sender
          );
        }
        break;
    }
  }

  joinRoom(ws: WebSocket, room: string): void {
    let members = this.rooms.get(room);
    if (!members) {
      members = new Set();
      this.rooms.set(room, members);
    }
    members.add(ws);
    this.meta.get(ws)?.rooms.add(room);
  }

  leaveRoom(ws: WebSocket, room: string): void {
    const members = this.rooms.get(room);
    if (members) {
      members.delete(ws);
      if (members.size === 0) this.rooms.delete(room);
    }
    this.meta.get(ws)?.rooms.delete(room);
  }

  /**
   * Broadcast to a room — O(room_size), not O(total_connections).
   * Skips sockets whose send buffer is backing up (backpressure).
   */
  broadcastToRoom(room: string, data: string, exclude?: WebSocket): void {
    const members = this.rooms.get(room);
    if (!members) return;

    for (const ws of members) {
      if (ws === exclude) continue;
      if (ws.readyState !== WebSocket.OPEN) continue;
      if (ws.bufferedAmount > 1024 * 64) continue; // Backpressure: skip slow clients.
      ws.send(data);
    }
  }

  private handleDisconnect(ws: WebSocket): void {
    const m = this.meta.get(ws);
    if (!m) return;

    // Remove from all rooms.
    for (const room of m.rooms) {
      this.leaveRoom(ws, room);
    }
    this.connectionCount--;
    // WeakMap entry is GC'd automatically when ws is collected.
  }

  /**
   * Heartbeat sweep: ping all connections, terminate unresponsive ones.
   * This prevents zombie connections from accumulating.
   */
  private startHeartbeat(): void {
    this.heartbeatInterval = setInterval(() => {
      this.wss.clients.forEach((ws) => {
        const m = this.meta.get(ws);
        if (!m) { ws.terminate(); return; }

        if (!m.isAlive) {
          // Did not respond to last ping — terminate.
          ws.terminate();
          return;
        }

        m.isAlive = false;
        ws.ping();
      });
    }, this.heartbeatMs);
  }

  getStats(): { connections: number; rooms: number; roomSizes: Record<string, number> } {
    const roomSizes: Record<string, number> = {};
    for (const [name, members] of this.rooms) {
      roomSizes[name] = members.size;
    }
    return { connections: this.connectionCount, rooms: this.rooms.size, roomSizes };
  }

  shutdown(): void {
    if (this.heartbeatInterval) clearInterval(this.heartbeatInterval);
    this.wss.clients.forEach((ws) => ws.close(1001, "Server shutting down"));
  }
}

// --- Server setup ---

const wss = new WebSocketServer({ port: 8080, perMessageDeflate: false });
const manager = new ConnectionManager(wss);

console.log("WebSocket server listening on ws://localhost:8080");

setInterval(() => {
  console.log("Stats:", manager.getStats());
}, 10_000);

process.on("SIGTERM", () => manager.shutdown());
```

Why this scales to 50k:

- **Room-indexed broadcasts** (`Map<string, Set<WebSocket>>`): broadcasting to a 500-member room in a 50k-connection server touches 500 sockets, not 50,000.
- **Heartbeat cleanup**: detects dead TCP connections that did not send a FIN (mobile disconnects, network drops). Without this, zombie sockets accumulate until you OOM.
- **Backpressure check** (`bufferedAmount > 64KB`): slow clients do not cause the send buffer to grow unbounded.
- **`perMessageDeflate: false`**: per-message compression uses ~300KB RAM per connection. At 50k connections, that is 15GB just for compression state. Disable it unless bandwidth is your bottleneck.
- **WeakMap for metadata**: connection metadata is garbage collected automatically when the socket object is freed.

I'm building a Node.js service that fetches user data from two APIs in parallel and merges the results. Most of the time it works fine, but intermittently the response is missing fields from one of the APIs. No errors in the logs.

```javascript
class UserService {
  async getUserProfile(userId) {
    let profile = {};

    this.fetchBasicInfo(userId).then(info => {
      profile.name = info.name;
      profile.email = info.email;
    });

    this.fetchPreferences(userId).then(prefs => {
      profile.theme = prefs.theme;
      profile.language = prefs.language;
    });

    // Give the APIs time to respond
    await new Promise(resolve => setTimeout(resolve, 100));

    return profile;
  }

  async fetchBasicInfo(userId) {
    const res = await fetch(`https://api.example.com/users/${userId}`);
    return res.json();
  }

  async fetchPreferences(userId) {
    const res = await fetch(`https://api.example.com/users/${userId}/prefs`);
    return res.json();
  }
}
```

I added the 100ms timeout to wait for both calls. Sometimes it's fine, sometimes I get `{ name: 'Alice' }` with no theme or language. What's going on?

This is a classic async race condition. You are firing off two promises but not actually awaiting them — the `setTimeout` is a guess, not a guarantee.

**The problem in detail:** `.then()` schedules a callback to run when the promise resolves, but it does not block execution. Your code creates both promises, then immediately starts a 100ms timer. If either API takes longer than 100ms — which will happen intermittently due to network jitter, server load, DNS resolution, etc. — the function returns before that `.then()` callback has run. The profile object is missing those fields.

There is a second bug: neither `.then()` chain has a `.catch()`, so API errors are silently swallowed as unhandled promise rejections. You will never see them in your logs.

**Fixed version using `Promise.all`:**

```javascript
class UserService {
  async getUserProfile(userId) {
    const [info, prefs] = await Promise.all([
      this.fetchBasicInfo(userId),
      this.fetchPreferences(userId),
    ]);

    return {
      name: info.name,
      email: info.email,
      theme: prefs.theme,
      language: prefs.language,
    };
  }

  async fetchBasicInfo(userId) {
    const res = await fetch(`https://api.example.com/users/${userId}`);
    if (!res.ok) throw new Error(`Basic info API returned ${res.status}`);
    return res.json();
  }

  async fetchPreferences(userId) {
    const res = await fetch(`https://api.example.com/users/${userId}/prefs`);
    if (!res.ok) throw new Error(`Preferences API returned ${res.status}`);
    return res.json();
  }
}
```

`Promise.all` runs both fetches in parallel and waits until both have resolved (or one rejects). The destructured result gives you both responses, guaranteed complete. If either call fails, the error propagates to the caller instead of vanishing. Never use `setTimeout` as a synchronization mechanism — it is always a race condition waiting to happen.

For `string` keys, they are functionally identical. The difference appears when you use a union type as the key.

**Where they behave the same:**

```typescript
// These two are equivalent:
type ScoresA = Record<string, number>;
type ScoresB = { [key: string]: number };

const a: ScoresA = { math: 95, english: 87 };  // OK
const b: ScoresB = { math: 95, english: 87 };  // OK
```

**Where they diverge -- union keys:**

```typescript
type Theme = "light" | "dark" | "system";

// Record enforces that ALL keys in the union must be present:
type ThemeColors = Record<Theme, string>;

const colors: ThemeColors = {
    light: "#ffffff",
    dark: "#1a1a1a",
    // ERROR: Property 'system' is missing
};

// Fixed:
const colorsFixed: ThemeColors = {
    light: "#ffffff",
    dark: "#1a1a1a",
    system: "#f0f0f0",  // Now all keys present
};
```

An index signature cannot do this. `{ [key: string]: string }` accepts any keys and requires none.

**Under the hood: `Record` is a mapped type**

```typescript
// This is Record's actual definition in lib.es5.d.ts:
type Record<K extends keyof any, T> = {
    [P in K]: T;
};
```

The `[P in K]` syntax iterates over each member of `K` and creates a property for it. When `K` is `string`, that is equivalent to an index signature. When `K` is a union like `"light" | "dark" | "system"`, it creates exactly those three required properties.

This same `[P in K]` pattern powers the entire utility type family:

```typescript
// Partial<T> makes all properties optional:
type Partial<T> = { [P in keyof T]?: T[P] };

// Required<T> makes all properties required:
type Required<T> = { [P in keyof T]-?: T[P] };

// Readonly<T> makes all properties readonly:
type Readonly<T> = { readonly [P in keyof T]: T[P] };

// Pick<T, K> keeps only specified keys:
type Pick<T, K extends keyof T> = { [P in K]: T[P] };
```

Once you understand `[P in K]: T[P]` as "for each key P in set K, the value type is T[P]", the entire utility type library becomes transparent.

```python
class QueueFromStacks:
    def __init__(self):
        self._in = []   # Push here
        self._out = []  # Pop from here

    def enqueue(self, val):
        self._in.append(val)

    def dequeue(self):
        if not self._out:
            while self._in:
                self._out.append(self._in.pop())
        if not self._out:
            raise IndexError('dequeue from empty queue')
        return self._out.pop()

    def __len__(self):
        return len(self._in) + len(self._out)
```

Amortized O(1) per operation. Each element is moved between stacks at most once.
